+    }
+    if (route == '/api/projects/$_project/mail-attachments')
+      return {'files': []};
+    if (route.endsWith('/classification')) {
+      return {
+        'id': 'a' * 32,
+        'kind': 'link',
+        'classification': 'restricted',
+        'revision': 0,
+        'source_fingerprint': 'a' * 64,
+      };
+    }
+    throw StateError('Unexpected navigation request: $path');
+  }
+}
